COMMENT ON TABLE "accounts" IS 'Tài khoản mới có role=user. Sau duyệt, đổi thành learner hoặc instructor; luôn đúng một role. Đăng nhập không đặt lại role. Giữ lịch sử học cũ khi chuyển role; quyền thao tác mới theo role hiện tại.';

COMMENT ON COLUMN "accounts"."email" IS 'Chuẩn hóa lowercase trước khi lưu';

COMMENT ON COLUMN "accounts"."password_hash" IS 'Không lưu mật khẩu thô';

COMMENT ON COLUMN "accounts"."role" IS 'Một role duy nhất: user / learner / instructor / admin. Role được thay thế khi duyệt, không thêm role thứ hai.';

COMMENT ON COLUMN "accounts"."target_overall_band" IS 'Mục tiêu IELTS tổng, 4.0..9.0 bước 0.5';

COMMENT ON COLUMN "accounts"."target_exam_date" IS 'Ngày thi mục tiêu nếu có';

COMMENT ON COLUMN "accounts"."status" IS 'active / suspended / deleted';

COMMENT ON TABLE "role_applications" IS 'Hồ sơ xin quyền dùng chung; requested_role=instructor chính là instructor application. Giữ quy tắc tài khoản mới là user và learner/instructor được duyệt sau. Một pending application mỗi applicant; chỉ admin duyệt; từ chối cần lý do. Approve kiểm tra role hiện tại và đổi accounts.role sang requested_role, cập nhật hồ sơ, notification và audit trong cùng transaction. Reject giữ nguyên role. Không tự cấp admin từ form này.';

COMMENT ON COLUMN "role_applications"."requested_role" IS 'learner / instructor; không cho xin admin';

COMMENT ON COLUMN "role_applications"."application_text" IS 'Lý do và trình độ/kinh nghiệm khi xin instructor';

COMMENT ON COLUMN "role_applications"."evidence_url" IS 'Minh chứng cho hồ sơ instructor nếu tiêu chí yêu cầu';

COMMENT ON COLUMN "role_applications"."status" IS 'pending / approved / rejected';

COMMENT ON TABLE "auth_tokens" IS 'Phiên đăng nhập và token khôi phục mật khẩu có thể thu hồi.';

COMMENT ON COLUMN "auth_tokens"."token_hash" IS 'Chỉ lưu hash của refresh/reset token';

COMMENT ON COLUMN "auth_tokens"."purpose" IS 'refresh / password_reset';

COMMENT ON COLUMN "auth_tokens"."consumed_at" IS 'Dùng một lần với password_reset';

COMMENT ON TABLE "skills" IS 'Bốn kỹ năng IELTS và các kỹ năng thành phần. Cây parent_id phải không có chu trình. Seed bốn kỹ năng gốc; kỹ năng con là đề xuất bổ sung cho Direction 3.';

COMMENT ON COLUMN "skills"."parent_id" IS 'NULL với Listening, Reading, Writing, Speaking';

COMMENT ON COLUMN "skills"."code" IS 'reading / reading.inference ...';

COMMENT ON TABLE "skill_prerequisites" IS 'Kiến thức tiên quyết để xây mastery map có quan hệ phụ thuộc. Hai skill khác nhau; đồ thị prerequisite không có chu trình.';

COMMENT ON COLUMN "skill_prerequisites"."minimum_mastery" IS '0..1';

COMMENT ON TABLE "categories" IS 'Danh mục do admin quản lý.';

COMMENT ON TABLE "courses" IS 'Khóa học do một giảng viên sở hữu. instructor_id phải có quyền instructor; API kiểm tra chủ sở hữu. Archive/ẩn khi đã có người học; không xóa dây chuyền lịch sử.';

COMMENT ON COLUMN "courses"."prerequisite_text" IS 'Điều kiện đầu vào mô tả bằng văn bản';

COMMENT ON COLUMN "courses"."status" IS 'draft / published / hidden / archived';

COMMENT ON COLUMN "courses"."is_featured" IS 'Admin chọn hiển thị nổi bật';

COMMENT ON TABLE "course_skills" IS 'Mức độ khó riêng theo từng kỹ năng của khóa học. Tổng weight của một course bằng 1; không cộng kỹ năng cha và con hai lần khi tính tổng.';

COMMENT ON COLUMN "course_skills"."initial_band" IS '4.0..9.0, giảng viên đặt; bước 0.5';

COMMENT ON COLUMN "course_skills"."current_difficulty_rating" IS 'Điểm nội bộ, không phải điểm thi IELTS chính thức';

COMMENT ON COLUMN "course_skills"."weight" IS '0 < weight <= 1';

COMMENT ON TABLE "course_prerequisites" IS 'Khóa học cần hoàn thành trước. Không tự tham chiếu; không tạo chu trình. Điều kiện kỹ năng vẫn được xét riêng.';

COMMENT ON TABLE "chapters" IS 'Tương ứng Unit trong ERD ban đầu.';

