COMMENT ON TABLE "lessons" IS 'Một lesson có một video và nhiều material/exercise. Bản nháp có thể chưa có video; trước publish phải có đúng một video. Thứ tự toàn khóa = chapters.position rồi lessons.position. required_watch_percentage là cấu hình; tiến độ thực tế thuộc enrollment. Không sửa threshold/required/order đã có người học mà không có quy trình chuyển dữ liệu.';

COMMENT ON COLUMN "lessons"."position" IS 'Số nguyên dương';

COMMENT ON COLUMN "lessons"."required_watch_percentage" IS '0 < giá trị <= 100; ngưỡng xem video do instructor đặt. Đây là %completion trong ERD cũ.';

COMMENT ON COLUMN "lessons"."status" IS 'draft / published / hidden / archived';

COMMENT ON TABLE "videos" IS 'Video riêng, không nằm trong lesson_materials. Lesson-Video 1:1 về số lượng tối đa; kiểm tra publish bảo đảm mỗi lesson published có đúng một video. Không thay video hoặc duration khi đã có progress; tạo bản mới hoặc chuyển dữ liệu có kiểm soát.';

COMMENT ON COLUMN "videos"."lesson_id" IS 'UNIQUE bảo đảm tối đa một video mỗi lesson';

COMMENT ON COLUMN "videos"."video_url" IS 'Object key hoặc URL ổn định; không lưu signed URL tạm thời';

COMMENT ON COLUMN "videos"."duration_seconds" IS '>0';

COMMENT ON TABLE "lesson_materials" IS 'Lesson 1:N Material. text cần text_content; audio/slides/file cần resource_url. Video và ngưỡng video không đặt ở bảng này. Học liệu bắt buộc phải được hoàn thành theo chính sách đánh dấu/xác nhận của hệ thống.';

COMMENT ON COLUMN "lesson_materials"."material_type" IS 'text / audio / slides / file; video dùng bảng videos riêng';

COMMENT ON COLUMN "lesson_materials"."resource_url" IS 'URL hoặc object key của học liệu không phải text';

COMMENT ON COLUMN "lesson_materials"."text_content" IS 'Nội dung khi material_type=text';

COMMENT ON COLUMN "lesson_materials"."duration_seconds" IS 'Có thể có với audio; nếu có phải >0';

COMMENT ON COLUMN "lesson_materials"."position" IS '>0';

COMMENT ON TABLE "lesson_skills" IS 'Bài học dạy kỹ năng nào và cần mức đầu vào nào.';

COMMENT ON COLUMN "lesson_skills"."minimum_mastery" IS '0..1, điều kiện bắt đầu';

COMMENT ON COLUMN "lesson_skills"."expected_mastery" IS '0..1, mục tiêu sau bài';

COMMENT ON TABLE "enrollments" IS 'Quan hệ Learner–Course; trạng thái tham gia và tiếp tục học. Resume lesson phải thuộc course. Re-enrol kích hoạt lại bản ghi cũ, giữ tiến độ; thay đổi ghi audit. completed_at có khi status=completed.';

COMMENT ON COLUMN "enrollments"."status" IS 'active / withdrawn / completed';

COMMENT ON TABLE "lesson_progress" IS 'Tiến độ của một người trong một bài. Lesson phải thuộc course của enrollment. completed cần video đạt ngưỡng, toàn bộ material required hoàn thành và toàn bộ exercise required có kết quả đạt. Không chỉ dựa vào nút frontend; bài nộp chờ chấm chưa đạt điều kiện.';

COMMENT ON COLUMN "lesson_progress"."status" IS 'in_progress / completed';

COMMENT ON TABLE "material_progress" IS 'Tiến độ riêng cho material không phải video. Material phải thuộc course của enrollment. Text/slides/file được đánh dấu hoàn thành theo rule nhóm; audio position nếu có nằm trong duration.';

COMMENT ON COLUMN "material_progress"."last_position_seconds" IS 'Dành cho audio nếu có; video resume dùng video_progress';

COMMENT ON TABLE "video_progress" IS 'Mỗi người có trạng thái xem riêng đối với video. Video thuộc course của enrollment. watched_seconds và watched_percentage tính từ hợp video_watch_segments; không lưu thêm phần trăm độc lập dễ mất đồng bộ.';

COMMENT ON COLUMN "video_progress"."last_position_seconds" IS '>=0 và <=duration; chỉ là vị trí resume, không phải thời lượng đã xem';

COMMENT ON COLUMN "video_progress"."completed_at" IS 'Cache khi đã đạt ngưỡng required_watch_percentage của lesson';

COMMENT ON TABLE "video_watch_segments" IS '0 <= start < end <= videos.duration_seconds; video thuộc course của enrollment. Tính độ dài hợp các đoạn, không cộng trùng. Server xác thực heartbeat để tua đến cuối không tự đạt ngưỡng. Đây là bằng chứng phát video tương đối, không chứng minh người học chú ý.';

COMMENT ON TABLE "assessments" IS 'Tương ứng Exercise trong ERD. Lesson 1:N Exercise; dùng chung cho đầu vào, quiz, cuối khóa, kiểm tra tuần và bài nộp. Lesson nếu có phải thuộc course; lesson_quiz và assignment cần lesson; course_final cần course. Khi lesson_id có giá trị, course_id cũng phải có và cùng khóa. Weekly cần assigned_learner_id và week_start; unique có điều kiện trên cặp này khi purpose=weekly. Ít nhất một trong time_limit_seconds/due_at; số lượng và thời lượng >0. File có question_count=NULL. Đóng băng cấu hình đã có attempt hoặc tạo assessment mới.';

COMMENT ON COLUMN "assessments"."course_id" IS 'NULL cho placement/weekly nền tảng';

COMMENT ON COLUMN "assessments"."lesson_id" IS 'Có khi quiz hoặc assignment của bài';

COMMENT ON COLUMN "assessments"."assigned_learner_id" IS 'Bài weekly cá nhân';

COMMENT ON COLUMN "assessments"."purpose" IS 'placement / lesson_quiz / course_final / weekly / assignment';

COMMENT ON COLUMN "assessments"."response_mode" IS 'quiz / file / mixed';

COMMENT ON COLUMN "assessments"."status" IS 'draft / published / closed';

COMMENT ON COLUMN "assessments"."question_count" IS 'Số câu lấy từ pool khi tạo attempt';

COMMENT ON COLUMN "assessments"."time_limit_seconds" IS 'NULL nếu không giới hạn thời lượng';

COMMENT ON COLUMN "assessments"."max_attempts" IS 'NULL nghĩa là không giới hạn';

COMMENT ON COLUMN "assessments"."passing_percent" IS '0..100';

COMMENT ON COLUMN "assessments"."week_start" IS 'Dành cho weekly cá nhân';

COMMENT ON COLUMN "assessments"."grading_rubric" IS 'Tiêu chí chấm Writing/Speaking hoặc bài nộp';

COMMENT ON TABLE "question_banks" IS 'Ngân hàng có metadata và owner; QuestionBank 1:N Question. Quyền sử dụng theo owner/admin; khi course_id có giá trị, bank thuộc khóa đó. Chỉ archive ngân hàng có lịch sử đề thi, không xóa dây chuyền questions/snapshots.';

COMMENT ON COLUMN "question_banks"."course_id" IS 'NULL cho ngân hàng placement/weekly toàn nền tảng';

COMMENT ON COLUMN "question_banks"."status" IS 'active / archived';

COMMENT ON TABLE "questions" IS 'Câu hỏi thuộc question_banks; một kỹ năng chính cho mỗi câu ở MVP. Essay do người chấm; câu hỏi chỉ được dùng khi có quyền với question bank; backend kiểm tra owner/admin và quyền creator. Không tự động chấm Writing/Speaking bằng trắc nghiệm.';

COMMENT ON COLUMN "questions"."question_bank_id" IS 'Mỗi question thuộc một ngân hàng';

COMMENT ON COLUMN "questions"."source_lesson_id" IS 'Để tạo weekly từ bài đã được miễn';

COMMENT ON COLUMN "questions"."question_type" IS 'single_choice / multiple_choice / short_answer / essay';

COMMENT ON COLUMN "questions"."media_url" IS 'Audio/hình/tài liệu dùng kèm câu hỏi';

COMMENT ON COLUMN "questions"."answer_key" IS 'Đáp án text và quy tắc chuẩn hóa; chỉ backend được đọc';

COMMENT ON COLUMN "questions"."status" IS 'draft / active / retired';

COMMENT ON TABLE "question_options" IS 'Các đáp án lựa chọn, tách khỏi câu hỏi. single_choice đúng một option đúng; multiple_choice ít nhất một option đúng; không trả is_correct trong API làm bài.';

COMMENT ON TABLE "assessment_questions" IS 'Pool câu hỏi được phép rút cho một bài đánh giá. question_count >= số câu required và <= tổng pool hợp lệ. Weekly tạo pool theo source_lesson_id của lesson_exemptions còn hiệu lực.';

COMMENT ON COLUMN "assessment_questions"."max_points" IS '>0';

COMMENT ON COLUMN "assessment_questions"."is_required" IS 'Luôn xuất hiện, các câu khác được rút ngẫu nhiên';

COMMENT ON TABLE "assessment_attempts" IS 'Mỗi lần thi hoặc mỗi lần nộp bài là một bản ghi riêng. Nếu có enrollment: learner và course phải khớp assessment. Chỉ 1 attempt in_progress mỗi learner/assessment; khóa transaction khi cấp attempt_number, kiểm tra max_attempts. 0<=score<=max_points; không nhận answer sau expires_at. assigned_learner phải khớp người thi.';

COMMENT ON COLUMN "assessment_attempts"."enrollment_id" IS 'NULL với placement/weekly toàn nền tảng';

COMMENT ON COLUMN "assessment_attempts"."status" IS 'in_progress / submitted / awaiting_grading / graded / cancelled';

COMMENT ON COLUMN "assessment_attempts"."expires_at" IS 'Server chốt từ thời lượng và deadline';

COMMENT ON COLUMN "assessment_attempts"."submission_reason" IS 'manual / timeout';

COMMENT ON COLUMN "assessment_attempts"."max_points" IS '>0, đóng băng cho attempt';

COMMENT ON COLUMN "assessment_attempts"."score" IS 'NULL trước khi chấm đủ';

COMMENT ON COLUMN "assessment_attempts"."is_passed" IS 'NULL trước khi có kết quả cuối';

COMMENT ON COLUMN "assessment_attempts"."graded_by" IS 'NULL khi auto-grade';

COMMENT ON TABLE "attempt_questions" IS 'Đề thực tế và thứ tự câu hỏi/đáp án đã rút ở mỗi lần thi. Câu phải thuộc assessment_questions tương ứng; snapshots bất biến sau khi bắt đầu. Không sinh lại đề khi reload/timeout.';

COMMENT ON COLUMN "attempt_questions"."skill_id" IS 'Snapshot kỹ năng của câu tại thời điểm thi';

COMMENT ON COLUMN "attempt_questions"."question_snapshot" IS 'Prompt, type, media, options kèm thứ tự đã random';

COMMENT ON COLUMN "attempt_questions"."answer_key_snapshot" IS 'Chỉ backend; không nằm trong response làm bài';

COMMENT ON COLUMN "attempt_questions"."max_points" IS '>0';

COMMENT ON TABLE "attempt_answers" IS 'Câu trả lời được autosave và điểm từng câu. Option phải tồn tại trong snapshot của chính câu đó; 0<=awarded_points<=attempt_questions.max_points. Sau khi submitted, chỉ quy trình chấm được cập nhật điểm.';

COMMENT ON COLUMN "attempt_answers"."answer_payload" IS 'Option IDs trong snapshot hoặc nội dung text';

COMMENT ON COLUMN "attempt_answers"."awarded_points" IS 'NULL nếu chưa chấm';

COMMENT ON TABLE "submission_files" IS 'Tệp nộp bài, hỗ trợ file viết và audio/video nói. Chỉ chủ attempt được nộp trước expires_at; giới hạn loại/kích thước file và quyền tải xuống.';

COMMENT ON COLUMN "submission_files"."object_key" IS 'Tệp trong object storage, không nhét binary vào DB';

COMMENT ON TABLE "lesson_exemptions" IS 'Bài được miễn bởi thuật toán, khác với đã học xong. Một exemption còn hiệu lực cho mỗi enrollment/lesson; lesson thuộc course, basis attempt thuộc cùng learner và đã graded. Miễn bài không ghi lesson_progress.completed.';

COMMENT ON COLUMN "lesson_exemptions"."revoked_at" IS 'Có thể thu hồi khi weekly phát hiện thiếu kiến thức';

COMMENT ON TABLE "learner_skill_states" IS 'Trạng thái hiện tại theo từng kỹ năng; cache để gợi ý nhanh. Không có state trước khi đủ dữ liệu thì hiển thị chưa đánh giá. Mapping rating→band/mastery phải có phiên bản, không coi là IELTS chính thức.';

COMMENT ON COLUMN "learner_skill_states"."ability_rating" IS 'Elo nội bộ';

COMMENT ON COLUMN "learner_skill_states"."estimated_band" IS '4.0..9.0 theo phạm vi proposal; có thể NULL khi chưa đủ bằng chứng';

COMMENT ON COLUMN "learner_skill_states"."mastery_score" IS '0..1, không tự đồng nhất với estimated_band';

COMMENT ON COLUMN "learner_skill_states"."target_band" IS 'Mục tiêu theo kỹ năng gốc';

COMMENT ON COLUMN "learner_skill_states"."uncertainty" IS 'Độ bất định nếu thuật toán có hỗ trợ';

COMMENT ON TABLE "learner_rating_events" IS 'Lịch sử thay đổi trình độ để vẽ trajectory và giải thích. source attempt cùng learner, đã graded. Cập nhật event và learner_skill_states trong một transaction; unique chống worker xử lý lặp. MVP chỉ placement/course_final/weekly là bằng chứng cập nhật rating, retake quiz không farm Elo.';

COMMENT ON COLUMN "learner_rating_events"."rating_before" IS 'NULL khi khởi tạo';

COMMENT ON COLUMN "learner_rating_events"."calculation_inputs" IS 'Lưu score, expected, K, difficulty tại thời điểm cập nhật';

COMMENT ON TABLE "course_reviews" IS 'Nhận xét và cảm nhận độ khó, tách khỏi ability rating. Chỉ learner đã completed được review; star_rating không dùng trực tiếp như IELTS band. MVP review chung cho course; cập nhật các skill theo weight bằng rule có phiên bản.';

COMMENT ON COLUMN "course_reviews"."star_rating" IS '1..5: chất lượng trải nghiệm';

COMMENT ON COLUMN "course_reviews"."perceived_difficulty" IS 'too_easy / appropriate / too_hard';

COMMENT ON COLUMN "course_reviews"."status" IS 'visible / hidden';

COMMENT ON TABLE "course_rating_events" IS 'Lịch sử điều chỉnh độ khó khóa học từ kết quả hoặc review. Đúng một nguồn attempt hoặc review; nguồn thuộc course; cặp course/skill tồn tại ở course_skills. Unique (source_attempt_id,skill_id) và (source_review_id,skill_id) khi khác NULL. Cập nhật event+course_skills atomically; review mỗi enrollment tác động tối đa một lần trong MVP.';

COMMENT ON TABLE "recommendations" IS 'Lưu gợi ý cùng lý do và đầu vào, phục vụ kiểm chứng thay đổi learning path. Mỗi batch chỉ thuộc một learner; recommend course published, phù hợp prerequisites; có thể suy ra chọn học qua enrollments. Baseline và adaptive phân biệt bằng algorithm_version.';

COMMENT ON COLUMN "recommendations"."batch_id" IS 'Nhóm các gợi ý trong cùng một lần chạy';

COMMENT ON COLUMN "recommendations"."input_snapshot" IS 'Learner ratings, course difficulty, prerequisites lúc gợi ý';

COMMENT ON TABLE "discussions" IS 'Q&A theo bài học, có trả lời theo thread. Reply phải cùng lesson; parent không có chu trình, MVP giới hạn một cấp reply. Learner chỉ truy cập thảo luận khóa mình đăng ký.';

COMMENT ON COLUMN "discussions"."is_resolved" IS 'Áp dụng cho bài gốc';

COMMENT ON COLUMN "discussions"."status" IS 'visible / hidden / deleted';

COMMENT ON TABLE "notifications" IS 'Thông báo cá nhân về nội dung, deadline, kết quả và kiểm duyệt.';

COMMENT ON COLUMN "notifications"."notification_type" IS 'new_content / deadline / result / moderation / weekly_test';

COMMENT ON COLUMN "notifications"."dedupe_key" IS 'Khóa sự kiện để worker retry không gửi trùng';

COMMENT ON TABLE "content_reports" IS 'Báo cáo nội dung vi phạm, có FK thật đến đối tượng. Chính xác một trong course_id/lesson_id/discussion_id/review_id khác NULL. Admin xử lý và ghi audit; có thể report lesson để chỉ ra học liệu vi phạm.';

COMMENT ON COLUMN "content_reports"."status" IS 'pending / reviewing / resolved / dismissed';

COMMENT ON TABLE "audit_logs" IS 'Lịch sử thao tác nhạy cảm của admin và hệ thống. Append-only; tài khoản ứng dụng không được sửa/xóa log. entity_id là snapshot để log còn tồn tại khi đối tượng bị archive.';

COMMENT ON COLUMN "audit_logs"."actor_id" IS 'NULL khi tác vụ hệ thống';

COMMENT ON COLUMN "audit_logs"."action" IS 'approve_instructor / suspend_user / hide_course ...';

COMMENT ON COLUMN "audit_logs"."entity_id" IS 'Snapshot định danh, cố ý không dùng FK polymorphic';

COMMENT ON COLUMN "audit_logs"."before_data" IS 'Loại bỏ password_hash, token và dữ liệu nhạy cảm';

